import React, { useEffect, useState } from 'react';
import { getHistory } from '../services/api';
import {
  ActivityTrendChart,
  PredictionHistoryChart,
  RiskPieChart,
  SleepTrendChart,
  StressTrendChart,
} from '../charts/TrendCharts';

export default function Analytics() {
  const [history, setHistory] = useState([]);

  useEffect(() => {
    getHistory().then((r) => setHistory(r.data.history || []));
  }, []);

  if (!history.length) {
    return (
      <div>
        <h2>Analytics Dashboard</h2>
        <p className="text-muted">No assessment data yet. Complete an assessment first.</p>
      </div>
    );
  }

  const charts = [
    ['Activity Trend', ActivityTrendChart],
    ['Sleep Trend', SleepTrendChart],
    ['Stress Trend', StressTrendChart],
    ['Depression Prediction History', PredictionHistoryChart],
    ['Risk Distribution', RiskPieChart],
  ];

  return (
    <div>
      <h2 className="mb-4">Analytics Dashboard</h2>
      <div className="row g-4">
        {charts.map(([title, Chart]) => (
          <div className="col-lg-6" key={title}>
            <div className="card card-mw p-3 h-100">
              <h6>{title}</h6>
              <Chart history={history} />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
